import ee, math
ee.Initialize(project='earthsense-436113')

# Geometry
geom = ee.Geometry.Polygon([[
  [-138.80, 58.95],
  [-138.80, 59.15],
  [-138.40, 59.15],
  [-138.40, 58.95],
  [-138.80, 58.95]
]])

def mask_scale_add_mndwi(img):
    # Mask using QA_PIXEL (C02 L2)
    qa = img.select('QA_PIXEL')
    # bits: 0 fill, 1 dilated cloud, 2 cirrus, 3 cloud, 4 cloud shadow, 5 snow
    mask = qa.bitwiseAnd(1<<0).eq(0) \
        .And(qa.bitwiseAnd(1<<1).eq(0)) \
        .And(qa.bitwiseAnd(1<<2).eq(0)) \
        .And(qa.bitwiseAnd(1<<3).eq(0)) \
        .And(qa.bitwiseAnd(1<<4).eq(0)) \
        .And(qa.bitwiseAnd(1<<5).eq(0))
    sat = img.select('QA_RADSAT')
    mask = mask.And(sat.eq(0))

    # Scale SR to reflectance
    sr = img.select(['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7']) \
            .multiply(0.0000275).add(-0.2)
    img = img.addBands(sr, overwrite=True).updateMask(mask)

    green = img.select('SR_B2')
    swir1 = img.select('SR_B5')
    mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI')
    return img.addBands(mndwi)

def build_col(start, end):
    l4 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2').filterBounds(geom).filterDate(start, end)
    l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterBounds(geom).filterDate(start, end)
    l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterBounds(geom).filterDate(start, end)
    return l4.merge(l5).merge(l7).map(mask_scale_add_mndwi)

def get_year_stats(year):
    # Primary window
    col = build_col(f"{year}-06-15", f"{year}-09-30")
    size = col.size().getInfo()
    if size == 0:
        # Wider window
        col = build_col(f"{year}-05-01", f"{year}-10-31")
        size = col.size().getInfo()
        if size == 0:
            # 3-year summer fallback
            col = build_col(f"{year-1}-05-01", f"{year+1}-10-31")
            size = col.size().getInfo()
            if size == 0:
                return {'status':'C1', 'msg': f"{year} Images: 0"}

    comp = col.median().clip(geom)

    # Valid pixels (after mask)
    try:
        valid_px = comp.select('SR_B2').reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom, scale=1000, maxPixels=1e9, tileScale=4
        ).get('SR_B2').getInfo()
    except Exception:
        return {'status':'C3', 'msg': f"{year} valid_px error"}
    if (valid_px is None) or int(valid_px) == 0:
        return {'status':'C2', 'msg': f"{year} Valid px: 0"}

    # Water mask and area
    water = comp.select('MNDWI').gt(0).selfMask().rename('water')
    try:
        water_px = water.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom, scale=1000, maxPixels=1e9, tileScale=4
        ).get('water').getInfo()
        water_area_m2 = water.multiply(ee.Image.pixelArea()).reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=geom, scale=1000, maxPixels=1e9, tileScale=4
        ).get('water').getInfo()
    except Exception:
        return {'status':'C3', 'msg': f"{year} area error"}

    if (water_area_m2 is None):
        return {'status':'C3', 'msg': f"{year} area None"}

    try:
        km2 = float(water_area_m2) / 1e6
    except Exception:
        return {'status':'C3', 'msg': f"{year} area invalid"}
    if math.isnan(km2) or km2 < 0:
        return {'status':'C3', 'msg': f"{year} area NaN'}

    # Crude coverage/cloud percent proxy
    total_pts = ee.Image.constant(1).reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=1000, maxPixels=1e9, tileScale=2
    ).get('constant').getInfo()
    cloud_pct = None
    if (total_pts is not None) and (int(total_pts) > 0):
        cloud_pct = max(0.0, 100.0 * (1.0 - (float(valid_px) / float(total_pts))))

    return {
        'status':'OK',
        'images': int(size),
        'valid_px': int(valid_px),
        'water_px': 0 if water_px is None else int(water_px),
        'km2': km2,
        'cloud_pct': None if cloud_pct is None else float(cloud_pct)
    }

def print_status_or_exit(year, stats):
    if stats.get('status') != 'OK':
        print(f"{year} Images/Status: {stats.get('msg')}")
        print(stats.get('status'))
        raise SystemExit

try:
    y1, y2 = 1984, 2010
    s1 = get_year_stats(y1); print_status_or_exit(y1, s1)
    s2 = get_year_stats(y2); print_status_or_exit(y2, s2)

    cp1 = 0.0 if s1['cloud_pct'] is None else round(s1['cloud_pct'], 1)
    cp2 = 0.0 if s2['cloud_pct'] is None else round(s2['cloud_pct'], 1)

    print(f"{y1} Images: {s1['images']}, Valid px: {s1['valid_px']}, Water px: {s1['water_px']}, Water km²: {s1['km2']:.2f}, Cloud%~: {cp1}")
    print(f"{y2} Images: {s2['images']}, Valid px: {s2['valid_px']}, Water px: {s2['water_px']}, Water km²: {s2['km2']:.2f}, Cloud%~: {cp2}")

    diff = s2['km2'] - s1['km2']
    pct = (diff / s1['km2'] * 100.0) if (s1['km2'] is not None and s1['km2'] > 0) else None
    print(f"Change {y2}-{y1}: {diff:.2f} km², Pct: {('NaN' if pct is None else f'{pct:.1f}%')}")

    if (s1['km2'] is None) or (s2['km2'] is None) or (pct is None) or math.isnan(s1['km2']) or math.isnan(s2['km2']):
        print("C3")
    else:
        decreased = diff < -0.05 * s1['km2']  # >5% decrease threshold
        print("A" if decreased else "B")
except SystemExit:
    pass
except Exception as e:
    print("D")
